window.despia = 'readvalue://';
return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
        observer.disconnect();
        reject(new Error('Timeout waiting for stored values'));
    }, 30000);

    const handleStoredValues = () => {
        if (window.storedValues) {
            try {
                const response = JSON.parse(decodeURIComponent(window.storedValues));
                clearTimeout(timeout);
                observer.disconnect();
                resolve(response);
            } catch (e) {
                clearTimeout(timeout);
                observer.disconnect();
                reject(e);
            }
        }
    };

    const observer = new MutationObserver(handleStoredValues);
    observer.observe(document.documentElement, {
        childList: true,
        characterData: true,
        subtree: true
    });

    handleStoredValues();
});
